# Generated by build.py from recipe.yml for recipe http-move-uploads-to-s3. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p store/uploads store2/uploads
cat > report.csv <<'EOF'
region,total
north,1200
south,950
EOF
cat > summary.csv <<'EOF'
total
2150
EOF
printf '%s\n' 'uploads land here' > store/uploads/readme.txt
printf '%s\n' 'uploads land here' > store2/uploads/readme.txt
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:*.s3.us-east-1.amazonaws.com"
surl --directory store --cert server.pem --key server.key --user AKIAIOSFODNN7EXAMPLE:s3cret --allow-uploads --list-directories -v --log-file surl.log s3://127.0.0.1:8080/ https://127.0.0.1:8081/ &
sleep 1
curl -sS --cacert server.pem -u AKIAIOSFODNN7EXAMPLE:s3cret -T report.csv https://127.0.0.1:8081/uploads/report.csv --next -sS --cacert server.pem --connect-to ::127.0.0.1:8080 -u AKIAIOSFODNN7EXAMPLE:s3cret -T summary.csv s3://uploads/summary.csv --next -sS --cacert server.pem --connect-to ::127.0.0.1:8080 -u AKIAIOSFODNN7EXAMPLE:s3cret s3://uploads/
kill $(jobs -p)
